export async function downloadBase64StringAsImage(base64String: string, filename: string = "image") {
if (typeof window === 'undefined') {
console.error("You are calling this function outside of the Browser.");
return;
}
// Credit:
// https://stackoverflow.com/a/74482141
const parts = base64String.match(/^data:(._?);base64,(._)$/);
if (!parts || parts.length !== 3) {
throw new Error('Invalid base64 string');
}
const [, mimeType, base64Data] = parts;

    const byteCharacters = atob(base64Data);
    const byteArrays = [];

    for (let offset = 0; offset < byteCharacters.length; offset += 512) {
        const slice = byteCharacters.slice(offset, offset + 512);

        const byteNumbers = new Array(slice.length);
        for (let i = 0; i < slice.length; i++) {
            byteNumbers[i] = slice.charCodeAt(i);
        }

        const byteArray = new Uint8Array(byteNumbers);
        byteArrays.push(byteArray);
    }

    const blob = new Blob(byteArrays, { type: mimeType });
    const url = URL.createObjectURL(blob);
    // Create a temporary download link
    const a = document.createElement('a');
    a.href = url;
    a.download = filename; // You can provide a desired file name here

    // Programmatically trigger the download
    document.body.appendChild(a);
    a.click();

    // Clean up: remove the temporary link and revoke the URL
    document.body.removeChild(a);
    URL.revokeObjectURL(url);

}
